// ---------- src/lib/config.js ----------
const __lib_config = (() => {
  const module = { exports: {} };
/**
 * Single source of truth for run configuration.
 * Values come from environment variables (PW_*) with safe defaults. Secrets never live here:
 * they are n8n credentials (OpenAI key, Facebook page token, Telegram bot token, Postgres).
 */

const DEFAULTS = {
  dry_run: true,                    // true = simulation: everything runs except the Facebook POST
  review_mode: 'auto',              // 'auto' = publish immediately, 'approval' = human approves a draft first (needs Telegram)
  publish_strategy: 'now',          // 'now' = publish when the run reaches the publish step, 'schedule' = Facebook scheduled post
  schedule_time: '18:00',           // local time used when publish_strategy = 'schedule'
  timezone: 'America/Denver',       // PlacidWay is US-based; used for "one post per day" and scheduling
  post_format: 'photo',             // 'photo' = image + caption (falls back to link post), 'link' = link-preview post
  fb_page_id: '',
  ig_user_id: '',                   // optional: Instagram professional account linked to the Page -> cross-post
  fb_graph_version: 'v23.0',
  fb_graph_base: '',
  llm_base_url: 'https://api.openai.com/v1',
  llm_model: 'gpt-4.1-mini',
  llm_judge_model: '',              // empty = same as llm_model
  llm_temperature: 0.7,
  variants: 3,                      // best-of-N generation
  telegram_chat_id: '',
  notify_on_success: true,
  review_timeout_hours: 20,
  user_agent: 'PlacidWayContentDemoBot/1.0 (+contact: automation-demo@example.com)',
  base_url: 'https://www.placidway.com',
  // Listing pages ordered by "modified date" act as the feed for each content type.
  sources: {
    article: '/search-medical-articles/All/All/1',
    package: '/search-medical-packages/All/All/1',
    answer: '/search-medical-answers/All/All/1',
  },
  // Variety rule: preferred content type per weekday (Mon..Sun). Falls back to any type.
  rotation: ['article', 'package', 'answer', 'article', 'package', 'answer', 'article'],
  detail_candidates: 2,             // how many detail pages we may fetch per run (fallback if the first is unusable)
  request_interval_ms: 1500,        // >= 1000 keeps us under 1 request/second
  max_attempts: 3,                  // transient failures (e.g. Facebook down) are retried on later runs up to this
  max_chars_before_link: 500,
  target_chars_before_link: 420,
  min_body_chars: 400,
  disclaimer: 'General information only, not medical advice.',
  brand_name: 'PlacidWay',
};

const ENV_MAP = {
  PW_DRY_RUN: ['dry_run', 'bool'],
  PW_REVIEW_MODE: ['review_mode', 'enum:auto,approval'],
  PW_PUBLISH_STRATEGY: ['publish_strategy', 'enum:now,schedule'],
  PW_SCHEDULE_TIME: ['schedule_time', 'hhmm'],
  PW_TIMEZONE: ['timezone', 'string'],
  PW_POST_FORMAT: ['post_format', 'enum:photo,link'],
  PW_FB_PAGE_ID: ['fb_page_id', 'string'],
  PW_IG_USER_ID: ['ig_user_id', 'string'],
  PW_FB_GRAPH_VERSION: ['fb_graph_version', 'string'],
  PW_FB_GRAPH_BASE: ['fb_graph_base', 'string'],      // override only for tests/mocks
  PW_LLM_BASE_URL: ['llm_base_url', 'string'],
  PW_LLM_MODEL: ['llm_model', 'string'],
  PW_LLM_JUDGE_MODEL: ['llm_judge_model', 'string'],
  PW_LLM_TEMPERATURE: ['llm_temperature', 'number'],
  PW_VARIANTS: ['variants', 'int:1:5'],
  PW_TELEGRAM_CHAT_ID: ['telegram_chat_id', 'string'],
  PW_NOTIFY_ON_SUCCESS: ['notify_on_success', 'bool'],
  PW_REVIEW_TIMEOUT_HOURS: ['review_timeout_hours', 'int:1:168'],
  PW_USER_AGENT: ['user_agent', 'string'],
  PW_BASE_URL: ['base_url', 'string'],
  PW_ROTATION: ['rotation', 'rotation'],
  PW_DETAIL_CANDIDATES: ['detail_candidates', 'int:1:3'],
  PW_REQUEST_INTERVAL_MS: ['request_interval_ms', 'int:1000:60000'],
  PW_MAX_ATTEMPTS: ['max_attempts', 'int:1:10'],
  PW_DISCLAIMER: ['disclaimer', 'string'],
};

function parseValue(raw, kind, key) {
  const v = String(raw).trim();
  if (kind === 'string') return v;
  if (kind === 'bool') {
    if (/^(1|true|yes|on)$/i.test(v)) return true;
    if (/^(0|false|no|off)$/i.test(v)) return false;
    throw new Error(`CONFIG_INVALID: ${key} must be true/false, got "${v}"`);
  }
  if (kind === 'number') {
    const n = Number(v);
    if (!Number.isFinite(n)) throw new Error(`CONFIG_INVALID: ${key} must be a number`);
    return n;
  }
  if (kind.startsWith('int:')) {
    const [, lo, hi] = kind.split(':').map(Number);
    const n = parseInt(v, 10);
    if (!Number.isInteger(n) || n < lo || n > hi) throw new Error(`CONFIG_INVALID: ${key} must be an integer ${lo}-${hi}`);
    return n;
  }
  if (kind.startsWith('enum:')) {
    const allowed = kind.slice(5).split(',');
    const lv = v.toLowerCase();
    if (!allowed.includes(lv)) throw new Error(`CONFIG_INVALID: ${key} must be one of ${allowed.join('|')}`);
    return lv;
  }
  if (kind === 'hhmm') {
    if (!/^([01]?\d|2[0-3]):[0-5]\d$/.test(v)) throw new Error(`CONFIG_INVALID: ${key} must be HH:MM`);
    return v;
  }
  if (kind === 'rotation') {
    const parts = v.split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
    const ok = ['article', 'package', 'answer', 'any'];
    if (parts.length !== 7 || parts.some((p) => !ok.includes(p))) {
      throw new Error(`CONFIG_INVALID: ${key} must list 7 values (Mon..Sun) from ${ok.join('|')}`);
    }
    return parts;
  }
  throw new Error(`unknown kind ${kind}`);
}

/**
 * @param {object} env  process-like env object ($env in n8n). May be empty/undefined when env access is blocked.
 * @param {object} overrides  optional values edited directly in the Config node.
 */
function buildConfig(env, overrides) {
  const cfg = JSON.parse(JSON.stringify(DEFAULTS));
  const e = env || {};
  for (const [envKey, [cfgKey, kind]] of Object.entries(ENV_MAP)) {
    const raw = e[envKey];
    if (raw === undefined || raw === null || String(raw).trim() === '') continue;
    cfg[cfgKey] = parseValue(raw, kind, envKey);
  }
  Object.assign(cfg, overrides || {});
  if (!cfg.llm_judge_model) cfg.llm_judge_model = cfg.llm_model;
  cfg.base_url = cfg.base_url.replace(/\/+$/, '');
  cfg.fb_graph_base = (cfg.fb_graph_base || `https://graph.facebook.com/${cfg.fb_graph_version}`).replace(/\/+$/, '');

  const problems = [];
  if (!cfg.dry_run && !cfg.fb_page_id) problems.push('PW_FB_PAGE_ID is required when PW_DRY_RUN=false');
  if (cfg.max_chars_before_link > 500) problems.push('max_chars_before_link may not exceed 500');
  if (cfg.review_mode === 'approval' && !cfg.telegram_chat_id) problems.push('PW_TELEGRAM_CHAT_ID is required when PW_REVIEW_MODE=approval (drafts are sent there)');
  if (problems.length) throw new Error('CONFIG_INVALID: ' + problems.join('; '));
  return cfg;
}

/** Reads $env defensively: n8n can block env access in nodes (N8N_BLOCK_ENV_ACCESS_IN_NODE). */
function readEnvSafely(getEnv) {
  try {
    const env = getEnv();
    const out = {};
    for (const k of Object.keys(ENV_MAP)) {
      try { if (env[k] !== undefined) out[k] = env[k]; } catch (e) { /* blocked */ }
    }
    return out;
  } catch (e) {
    return {};
  }
}

module.exports = { DEFAULTS, ENV_MAP, buildConfig, readEnvSafely, parseValue };

  return module.exports;
})();

// ---------- src/lib/util.js ----------
const __lib_util = (() => {
  const module = { exports: {} };
/**
 * Small, dependency-free helpers shared by every Code node.
 * This file is inlined into n8n Code nodes by scripts/build-workflows.js,
 * so it must not require anything outside src/lib.
 */

const NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '–', mdash: '—',
  lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', hellip: '…', bull: '•', middot: '·',
  copy: '©', reg: '®', trade: '™', eacute: 'é', aacute: 'á', iacute: 'í', oacute: 'ó',
  uacute: 'ú', ntilde: 'ñ', uuml: 'ü', ouml: 'ö', auml: 'ä', ccedil: 'ç', deg: '°',
  euro: '€', pound: '£', yen: '¥', times: '×', frac12: '½', rarr: '→', larr: '←',
};

function decodeEntities(str) {
  if (!str) return '';
  return String(str).replace(/&(#x[0-9a-f]+|#\d+|[a-z][a-z0-9]*);/gi, (m, code) => {
    if (code[0] === '#') {
      const n = code[1] === 'x' || code[1] === 'X' ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
      if (!Number.isFinite(n) || n <= 0 || n > 0x10ffff) return m;
      try { return String.fromCodePoint(n); } catch (e) { return m; }
    }
    const v = NAMED_ENTITIES[code.toLowerCase()];
    return v === undefined ? m : v;
  });
}

function collapseWhitespace(str) {
  return String(str || '').replace(/[\s ​]+/g, ' ').trim();
}

/** Strip tags and decode entities, producing a single clean line of text. */
function htmlToText(html) {
  return collapseWhitespace(
    decodeEntities(
      String(html || '')
        .replace(/<br\s*\/?>/gi, ' ')
        .replace(/<[^>]+>/g, ' ')
    )
  );
}

/**
 * Minimal URL parser/resolver. n8n's Code-node sandbox (task runner) has no global `URL`, so we cannot
 * rely on it. Handles absolute, protocol-relative, root-relative and relative references.
 * @returns {{protocol:string, hostname:string, port:string, host:string, origin:string, pathname:string, search:string, hash:string, href:string}|null}
 */
function parseUrl(raw, base) {
  if (raw === undefined || raw === null) return null;
  let s = String(raw).trim();
  if (!s) return null;
  const ABS = /^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/;
  let m = s.match(ABS);
  if (!m) {
    if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(s)) return null; // mailto:, javascript:, data: ...
    const b = parseUrl(base);
    if (!b) return null;
    if (s.startsWith('//')) s = `${b.protocol}${s}`;
    else if (s.startsWith('/')) s = `${b.origin}${s}`;
    else if (s.startsWith('?')) s = `${b.origin}${b.pathname}${s}`;
    else if (s.startsWith('#')) s = `${b.origin}${b.pathname}${b.search}${s}`;
    else s = `${b.origin}${b.pathname.replace(/[^/]*$/, '')}${s}`;
    m = s.match(ABS);
    if (!m) return null;
  }
  const protocol = m[1].toLowerCase() + ':';
  const authority = m[2].replace(/^.*@/, '');
  const hm = authority.match(/^(\[[^\]]+\]|[^:]*)(?::(\d*))?$/);
  if (!hm || !hm[1]) return null;
  const hostname = hm[1].toLowerCase();
  const defaultPort = (protocol === 'https:' && hm[2] === '443') || (protocol === 'http:' && hm[2] === '80');
  const port = hm[2] && !defaultPort ? hm[2] : '';
  // normalise dot segments
  const segs = [];
  for (const seg of (m[3] || '/').split('/')) {
    if (seg === '..') { if (segs.length > 1) segs.pop(); } else if (seg !== '.') segs.push(seg);
  }
  let pathname = segs.join('/');
  if (!pathname.startsWith('/')) pathname = '/' + pathname;
  const search = m[4] && m[4] !== '?' ? m[4] : '';
  const hash = m[5] && m[5] !== '#' ? m[5] : '';
  const host = hostname + (port ? `:${port}` : '');
  const origin = `${protocol}//${host}`;
  return { protocol, hostname, port, host, origin, pathname, search, hash, href: origin + pathname + search + hash };
}

/** Lower-cased host, no fragment, no query, no trailing slash. Path case is preserved. */
function normalizeUrl(raw, base) {
  if (!raw) return null;
  const u = parseUrl(raw, base);
  if (!u || !/^https?:$/.test(u.protocol)) return null;
  const protocol = /(^|\.)placidway\.com$/.test(u.hostname) ? 'https:' : u.protocol; // the live site is HTTPS-only
  return `${protocol}//${u.host}${u.pathname.replace(/\/+$/, '')}`;
}

/** Map a PlacidWay URL to a stable content key such as "article:4617" (slug/subdomain independent). */
const CONTENT_PATTERNS = [
  { type: 'article', re: /\/article\/(\d+)(?:\/|$)/i },
  { type: 'package', re: /\/package\/(\d+)(?:\/|$)/i },
  { type: 'answer', re: /\/answer-detail\/(\d+)(?:\/|$)/i },
];

function contentKeyFromUrl(url, extraHosts) {
  if (!url) return null;
  const parsed = parseUrl(url);
  if (!parsed) return null;
  const host = parsed.hostname;
  const allowed = /(^|\.)placidway\.com$/.test(host) || (extraHosts || []).includes(host);
  if (!allowed) return null;
  for (const p of CONTENT_PATTERNS) {
    const m = url.match(p.re);
    if (m) return { type: p.type, id: m[1], key: `${p.type}:${m[1]}` };
  }
  return null;
}

/** Postgres parameters are passed as one base64 JSON blob: immune to the comma-splitting of
 *  "Query Parameters" and to SQL injection; decoded in SQL with convert_from(decode($1,'base64'),'UTF8')::jsonb */
function toB64Json(obj) {
  const json = JSON.stringify(obj);
  if (typeof Buffer !== 'undefined') return Buffer.from(json, 'utf8').toString('base64');
  return btoa(unescape(encodeURIComponent(json)));
}

function escapeTelegramHtml(str) {
  return String(str == null ? '' : str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function escapeAttr(str) {
  return escapeTelegramHtml(str).replace(/"/g, '&quot;');
}

function truncate(str, max) {
  const s = String(str || '');
  const chars = [...s];
  if (chars.length <= max) return s;
  return chars.slice(0, Math.max(0, max - 1)).join('').trimEnd() + '…';
}

/** Character count as Facebook / humans see it (code points, not UTF-16 units). */
function charLength(str) {
  return [...String(str || '')].length;
}

/** Lower-case, unify quotes/dashes, strip punctuation except digits/letters, collapse spaces. */
function normalizeForMatch(str) {
  return collapseWhitespace(
    String(str || '')
      .toLowerCase()
      .replace(/[‘’`´]/g, "'")
      .replace(/[“”]/g, '"')
      .replace(/[‐‑‒–—―]/g, '-')
      .replace(/(\d),(\d{3})/g, '$1$2')
      .replace(/[^a-z0-9$%.\-' ]+/g, ' ')
      .replace(/(\D)\.|\.(\D|$)/g, '$1 $2')
  );
}

/** Pulls the provider's own error text out of n8n's wrapped messages like 400 - "{\"error\":{\"message\":\"...\"}}". */
function innerApiMessage(error) {
  const flat = typeof error === 'string' ? error : JSON.stringify(error || {});
  const msgs = [...flat.matchAll(/\\*"message\\*"\s*:\s*\\*"((?:[^"\\]|\\[^"])*)/g)]
    .map((m) => m[1].replace(/\\+$/, '').replace(/\\+(["/])/g, '$1'))
    .filter((m) => m && !/^\d{3} - $/.test(m));
  return msgs.length ? msgs[msgs.length - 1] : null;
}

function safeJsonParse(text) {
  if (text && typeof text === 'object') return text;
  if (typeof text !== 'string') return null;
  let t = text.trim();
  const fence = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fence) t = fence[1];
  try { return JSON.parse(t); } catch (e) { /* fall through */ }
  const first = t.indexOf('{');
  const last = t.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(t.slice(first, last + 1)); } catch (e) { return null; }
  }
  return null;
}

module.exports = {
  parseUrl, decodeEntities, collapseWhitespace, htmlToText, normalizeUrl, contentKeyFromUrl, toB64Json,
  escapeTelegramHtml, escapeAttr, truncate, charLength, normalizeForMatch, safeJsonParse, innerApiMessage,
};

  return module.exports;
})();

// ---------- src/nodes/daily/config.js ----------
// Config: builds the run configuration from PW_* environment variables (with safe defaults).
const { buildConfig, readEnvSafely } = __lib_config;
const { toB64Json } = __lib_util;

// Optional: edit values here to override environment variables (e.g. { dry_run: false }).
const OVERRIDES = {};

const cfg = buildConfig(readEnvSafely(() => $env), OVERRIDES);
const manual = $('Manual run').isExecuted;
const run = {
  execution_id: String($execution.id),
  trigger_mode: manual ? 'manual' : 'schedule',
  started_at: new Date().toISOString(),
  // Manual runs always go ahead (handy for demos); scheduled slots stop once today's post exists.
  force: manual,
};
const counted = ['published', 'scheduled', 'pending_review', 'approved'].concat(cfg.dry_run ? ['dry_run'] : []);
return [{
  json: {
    cfg,
    run,
    db_payload_b64: toB64Json({
      execution_id: run.execution_id,
      trigger_mode: run.trigger_mode,
      review_mode: cfg.review_mode,
      dry_run: cfg.dry_run,
      timezone: cfg.timezone,
      counted_statuses: counted,
      config: { ...cfg, llm_base_url: cfg.llm_base_url, fb_page_id: cfg.fb_page_id ? 'set' : '' },
    }),
  },
}];

