  const parts = [error.message, error.description].filter(Boolean).map(clean);
  if (error.httpCode && !/^\d{3}\b/.test(parts[0] || '')) parts.unshift(`HTTP ${error.httpCode}`);
  return parts.join(' | ') || JSON.stringify(error).slice(0, 500);
