    const base = new Date(now.getTime() + addDays * 86400000);
    const { y, m, d } = localDateParts(base, timeZone);
    let guess = Date.UTC(y, m - 1, d, hh, mm, 0);
    guess -= tzOffsetMinutes(new Date(guess), timeZone) * 60000;
